#[cfg(test)]
mod tests {
    use super::*;
    use core::f64::consts::PI;
    #[test]
    fn huffman_tree_sizes_and_root_leaf() {
        assert_eq!(F_HUFF_IID_DEF.len(), 28);
        assert_eq!(F_HUFF_IID_FINE.len(), 60);
        assert_eq!(F_HUFF_ICC.len(), 14);
        assert_eq!(F_HUFF_IPD.len(), 7);
        // Row 0 of every tree carries the most-probable symbol (leaf -31).
        for t in [
            &F_HUFF_IID_DEF[..],
            &T_HUFF_IID_DEF,
            &F_HUFF_ICC,
            &F_HUFF_IPD,
            &F_HUFF_OPD,
        ] {
            assert!(t[0][0] == -31 || t[0][1] == -31);
        }
    }
    #[test]
    fn iid_icc_dequant_anchors() {
        assert!((SF_IID_NORMAL[7] - 1.0).abs() < 1e-9); // center == 1.0
        assert!((SF_IID_FINE[15] - 1.0).abs() < 1e-9);
        assert!((COS_ALPHAS[5] - 0.70710678).abs() < 1e-6);
        assert!((SIN_ALPHAS[5] - 0.70710678).abs() < 1e-6);
        for q in 0..8 {
            // rho = 2*cos^2-1 reproduces icc_invq
            let rho = 2.0 * f64::from(COS_ALPHAS[q]).powi(2) - 1.0;
            assert!((rho - f64::from(ICC_INVQ[q])).abs() < 1e-3);
        }
    }
    #[test]
    fn ipdopd_angle_and_band_maps() {
        for q in 0..8 {
            let a = q as f64 * PI / 4.0;
            assert!((f64::from(IPDOPD_COS[q]) - a.cos()).abs() < 1e-6);
            assert!((f64::from(IPDOPD_SIN[q]) - a.sin()).abs() < 1e-6);
        }
        assert_eq!(FF_K_TO_I_20.len(), 71);
        assert_eq!(FF_K_TO_I_34.len(), 91);
        assert_eq!(*FF_K_TO_I_20.iter().max().unwrap(), 19);
        assert_eq!(*FF_K_TO_I_34.iter().max().unwrap(), 33);
    }
    #[test]
    fn hybrid_proto_centers_and_allpass_gains() {
        // proto center coeff == 1/bands (last of the 7 half-coeffs).
        assert!((f64::from(G0_Q12[6]) - 1.0 / 12.0).abs() < 1e-6);
        assert!((f64::from(G1_Q8[6]) - 1.0 / 8.0).abs() < 1e-6);
        assert!((f64::from(G2_Q4[6]) - 0.25).abs() < 1e-6);
        assert_eq!(HYB_FILT_12.len(), 12);
        assert_eq!(HYB_FILT_6.len(), 6);
        assert!((f64::from(FILTER_A[0]) - 0.65143905753106).abs() < 1e-9);
        assert_eq!(NUM_SAMPLE_DELAY_SER, [3, 4, 5]);
    }
}

#[cfg(test)]
mod more_tests {
    use super::*;
    #[test]
    fn v2d_beta_gamma_dims_and_anchors() {
        assert_eq!(COS_BETAS_NORMAL.len(), 8);
        assert_eq!(SIN_BETAS_NORMAL.len(), 8);
        assert_eq!(COS_BETAS_FINE.len(), 16);
        assert_eq!(SIN_BETAS_FINE.len(), 16);
        assert_eq!(SINCOS_ALPHAS_B_NORMAL.len(), 15);
        assert_eq!(SINCOS_ALPHAS_B_FINE.len(), 31);
        assert_eq!(COS_GAMMAS_NORMAL.len(), 8);
        assert_eq!(COS_GAMMAS_FINE.len(), 16);
        assert_eq!(SIN_GAMMAS_NORMAL.len(), 8);
        assert_eq!(SIN_GAMMAS_FINE.len(), 16);
        assert!((f64::from(COS_BETAS_NORMAL[1][7]) - 0.9681727381).abs() < 1e-6);
        assert!((f64::from(SIN_BETAS_NORMAL[7][7]) - (-0.9958922202)).abs() < 1e-6);
        assert!((f64::from(COS_GAMMAS_NORMAL[7][7]) - 0.9984265591).abs() < 1e-6);
        assert!((f64::from(SIN_GAMMAS_NORMAL[7][7]) - 0.0560750040).abs() < 1e-5);
    }
    #[test]
    fn allpass_phase_tables_dims_first_entries_and_unit_magnitude() {
        assert_eq!(PHI_FRACT_QMF.len(), 64);
        assert_eq!(PHI_FRACT_SUBQMF20.len(), 12);
        assert_eq!(PHI_FRACT_SUBQMF34.len(), 32);
        assert_eq!(Q_FRACT_ALLPASS_QMF.len(), 64);
        assert_eq!(Q_FRACT_ALLPASS_SUBQMF20.len(), 12);
        assert_eq!(Q_FRACT_ALLPASS_SUBQMF34.len(), 32);
        assert!((f64::from(PHI_FRACT_QMF[0].re) - 0.8181497455).abs() < 1e-6);
        // QMF allpass phase tables are FFmpeg's exp(−iθ) convention (conjugate
        // of faad2: imaginary parts negated); faad2 was +0.5750052333 /
        // +0.6252426505. Re-conjugating drops PS conformance SNR to ~11 dB.
        assert!((f64::from(PHI_FRACT_QMF[0].im) + 0.5750052333).abs() < 1e-6);
        assert!((f64::from(Q_FRACT_ALLPASS_QMF[0][0].re) - 0.7804303765).abs() < 1e-6);
        assert!((f64::from(Q_FRACT_ALLPASS_QMF[0][0].im) + 0.6252426505).abs() < 1e-6);
        // Regression guard: FFmpeg convention ⇒ negative imaginary parts.
        assert!(PHI_FRACT_QMF[0].im < 0.0);
        assert!(Q_FRACT_ALLPASS_QMF[0][0].im < 0.0);
        // SubQmf allpass phase tables are FFmpeg `ps_tableinit` values in
        // f_center order (aacps_tablegen.h), NOT faad2. FFmpeg phi_fract[0][0],
        // f_center = -3/8: (0.896, 0.444) -- was faad2 (0.988, 0.153).
        assert!((f64::from(PHI_FRACT_SUBQMF20[0].re) - 0.8962930).abs() < 1e-6);
        assert!((f64::from(PHI_FRACT_SUBQMF20[0].im) - 0.4434623).abs() < 1e-6);
        // FFmpeg Q_fract_allpass[0][0][0]: was faad2 0.9857769012 -> 0.8744081.
        assert!((f64::from(Q_FRACT_ALLPASS_SUBQMF20[0][0].re) - 0.8744081).abs() < 1e-6);
        // FFmpeg Q_fract_allpass[1][6][0]: was faad2 0.2181432247 -> 0.1071317.
        assert!((f64::from(Q_FRACT_ALLPASS_SUBQMF34[6][0].re) - 0.1071317).abs() < 1e-6);
        // Real hybrid sub-bands are unit-magnitude; SUBQMF20[10],[11] are unused
        // zero padding (decorrelate reads only k < n_hyb == 10).
        for c in PHI_FRACT_QMF
            .iter()
            .chain(PHI_FRACT_SUBQMF20[..10].iter())
            .chain(PHI_FRACT_SUBQMF34.iter())
        {
            let m = (f64::from(c.re) * f64::from(c.re) + f64::from(c.im) * f64::from(c.im)).sqrt();
            assert!((m - 1.0).abs() < 1e-4);
        }
        assert_eq!(PHI_FRACT_SUBQMF20[10].re, 0.0);
        assert_eq!(PHI_FRACT_SUBQMF20[11].re, 0.0);
    }
    #[test]
    fn delay_d_step_function() {
        assert_eq!(DELAY_D.len(), 64);
        assert_eq!(DELAY_D[0], 14);
        assert_eq!(DELAY_D[34], 14);
        assert_eq!(DELAY_D[35], 1);
        assert_eq!(DELAY_D[63], 1);
    }
    #[test]
    fn pd_smooth_dims_and_unit_magnitude() {
        assert_eq!(PD_RE_SMOOTH.len(), 512);
        assert_eq!(PD_IM_SMOOTH.len(), 512);
        for i in 0..512 {
            let m =
                (f64::from(PD_RE_SMOOTH[i]).powi(2) + f64::from(PD_IM_SMOOTH[i]).powi(2)).sqrt();
            assert!((m - 1.0).abs() < 1e-4, "i={i} mag={m}");
        }
        // pd0=pd1=pd2=0 -> angle 0 -> (cos,sin)=(1,0) for every term -> re=1,im=0.
        assert!((f64::from(PD_RE_SMOOTH[0]) - 1.0).abs() < 1e-5);
        assert!(f64::from(PD_IM_SMOOTH[0]).abs() < 1e-5);
    }
    #[test]
    fn hyb_filt_outer_dims() {
        assert_eq!(HYB_FILT_12.len(), 12);
        assert_eq!(HYB_FILT_8.len(), 8);
        assert_eq!(HYB_FILT_4.len(), 4);
        assert_eq!(HYB_FILT_6.len(), 6);
    }
    #[test]
    fn v6_config_constants() {
        assert_eq!(NUM_ENV_TAB, [[0, 1, 2, 4], [1, 2, 3, 4]]);
        assert_eq!(NR_IIDICC_PAR_TAB, [10, 20, 34, 10, 20, 34]);
        assert_eq!(NR_IIDOPD_PAR_TAB, [5, 11, 17, 5, 11, 17]);
        assert!((DECAY_SLOPE - 0.05).abs() < 1e-6);
        assert!((ALPHA_DECAY - 0.76592833836465).abs() < 1e-6);
        assert!((ALPHA_SMOOTH - 0.25).abs() < 1e-6);
        assert!((GAMMA - 1.5).abs() < 1e-6);
        assert_eq!(NEGATE_IPD_MASK, 0x1000);
    }
}
